class FieldValidator {
  static String? required(String value) {
    if (value.trim().isEmpty) {
      return 'Trường này không được để trống';
    }
    return null;
  }

  static String? email(String value) {
    if (!value.contains('@') || !value.substring(value.indexOf('@') + 1).contains('.')) {
      return 'Email không hợp lệ';
    }
    return null;
  }

  static String? minLength(String value, int min) {
    if (value.length < min) {
      return 'Tối thiểu $min ký tự';
    }
    return null;
  }

  static String? maxLength(String value, int max) {
    if (value.length > max) {
      return 'Tối đa $max ký tự';
    }
    return null;
  }
}

void main() {
  print('Empty: ${FieldValidator.required("")}');
  print('Name: ${FieldValidator.required("Alice")}');
  print('Bad email: ${FieldValidator.email("invalid")}');
  print('Good email: ${FieldValidator.email("a@b.com")}');
  print('Short: ${FieldValidator.minLength("hi", 3)}');
  print('Long enough: ${FieldValidator.minLength("hello", 3)}');
  print('Too long: ${FieldValidator.maxLength("toolong", 5)}');
}

