class FormState {
  final Map<String, String> _values = {};
  final Map<String, String> _initialValues = {};
  bool _dirty = false;

  FormState(Map<String, String> initialValues) {
    _values.addAll(initialValues);
    _initialValues.addAll(initialValues);
  }

  String getValue(String field) {
    return _values[field] ?? '';
  }

  void setValue(String field, String value) {
    _values[field] = value;
    if (_initialValues[field] != value) {
      _dirty = true;
    }
  }

  bool isDirty() {
    return _dirty;
  }

  Map<String, String?> validate(Map<String, String? Function(String)> validators) {
    final errors = <String, String?>{};
    for (final entry in validators.entries) {
      final value = _values[entry.key] ?? '';
      errors[entry.key] = entry.value(value);
    }
    return errors;
  }

  Map<String, String>? submit() {
    if (_dirty) return null;
    return Map.from(_values);
  }
}

void main() {
  final form = FormState({'name': '', 'email': ''});
  form.setValue('name', 'Alice');
  form.setValue('email', 'invalid');

  print('Dirty: ${form.isDirty()}');
  print('Name: ${form.getValue('name')}');

  final errors = form.validate({
    'name': (v) => v.isEmpty ? 'Required' : null,
    'email': (v) => v.contains('@') ? null : 'Invalid email',
  });
  print('Errors: $errors');
  print('Submit: ${form.submit()}');
}

