class FormWizard {
  final List<String> _steps;
  int _currentIndex = 0;
  final Map<String, Map<String, dynamic>> _data = {};

  FormWizard(this._steps) {
    for (final step in _steps) {
      _data[step] = {};
    }
  }

  String currentStep() {
    return _steps[_currentIndex];
  }

  bool next() {
    if (_currentIndex >= _steps.length - 1) return false;
    _currentIndex++;
    return true;
  }

  bool previous() {
    if (_currentIndex <= 0) return false;
    _currentIndex--;
    return true;
  }

  bool isFirst() {
    return _currentIndex == 0;
  }

  bool isLast() {
    return _currentIndex == _steps.length - 1;
  }

  Map<String, dynamic> getStepData(String step) {
    return Map.from(_data[step] ?? {});
  }

  void setStepData(String step, Map<String, dynamic> data) {
    if (_data.containsKey(step)) {
      _data[step] = data;
    }
  }

  String summary() {
    final parts = _steps.map((s) {
      final count = _data[s]?.length ?? 0;
      return '$s: $count fields';
    }).join(', ');
    return 'Wizard(${_steps.length} steps): [$parts]';
  }
}

void main() {
  final wizard = FormWizard(['Personal', 'Address', 'Review']);
  print('Current: ${wizard.currentStep()}');

  wizard.setStepData('Personal', {'name': 'Alice', 'age': '25'});
  wizard.next();
  print('Current: ${wizard.currentStep()}');

  wizard.setStepData('Address', {'street': '123 Main St'});
  wizard.next();
  print('Current: ${wizard.currentStep()}');
  print('Is last: ${wizard.isLast()}');
  print(wizard.summary());
}
